          "backlog": true,
          "hf_upvotes": null,
          "score": 0.0,
          "score_why": "가점 없음",
          "state": "풀이 끝",
          "keywords": [],
          "ai": {
            "easy1_title": "시각 상태 공간 모델의 예측 결과를 설명하기가 왜 이렇게 어려운 걸까요",
            "easy1_desc": "시각 상태 공간 모델(VMamba)은 입력값에 따라 선택적으로 정보를 처리하는 방식이라서, 어떤 특징이 예측에 기여했는지 콕 집어내기가 매우 어렵거든요. 모델 내부에서 정보가 순환하고 공유되는 경로가 복잡하게 얽혀 있기 때문인데요. 뭔 소리냐면, 모델이 왜 그런 판단을 내렸는지 그 과정을 추적하는 게 기존 방식으로는 잘 안 된다는 말이에요.",
            "easy1_evidence": "Attributing predictions of visual state-space models remains challenging because input-dependent selective dynamics couple feature selection, recurrent state propagation, and shared computational pathways.",
            "easy2_title": "참조 기반의 새로운 분석 도구로 예측의 근거를 명확히 찾아냈습니다",
            "easy2_desc": "연구진은 MambaLIFT라는 새로운 분석 프레임워크를 도입해서 VMamba가 예측한 결과를 공간 위치나 블록별로 쪼개어 분석해 봤는데요. 이 방식은 모델의 계산 그래프를 따라 기여도를 전파하는데, 수치적으로도 매우 정확하게 보존된다는 장점이 있어요. 기존 방식인 MambaLRP보다 픽셀을 뒤집어 확인하는 실험에서 더 높은 정확도를 보였거든요. 다만, 이 분석이 인과관계를 완벽히 증명하는 것은 아니라는 점도 연구진은 분명히 했습니다.",
            "easy2_evidence": "We introduce MambaLIFT, a reference-based, multiplier-first attribution framework for VMamba that propagates contributions through its computational graph using interaction-aware rules for selective-scan injection, recurrent memory, LayerNorm, and shared pathways.",
            "topic": "VMamba 모델의 예측 기여도를 분석하기 위해 참조 기반의 메커니즘 인식 기법인 MambaLIFT를 제안하고 그 성능을 검증한 연구예요.",
            "topic_evidence": "We introduce MambaLIFT, a reference-based, multiplier-first attribution framework for VMamba that propagates contributions through its computational graph using interaction-aware rules for selective-scan injection, recurrent memory, LayerNorm, and shared pathways.",
            "points": [
              {
                "subtitle": "MambaLIFT 분석 프레임워크",
                "desc": "VMamba 모델의 예측값을 참조값과의 차이로 분해하여 공간 위치, 블록, 스캔 방향 등 다양한 메커니즘별로 기여도를 계산합니다. 모델의 복잡한 계산 경로를 따라 정보를 전파하는 방식을 사용한 거예요.",
                "evidence": "MambaLIFT decomposes the reference-relative class-logit difference, \\(f_c(x)-f_c(x^0)\\), by spatial position, VSS block, scan direction, and computational mechanism."
              },
              {
                "subtitle": "성능 평가 및 정확도",
                "desc": "ImageNet-1K 데이터셋으로 VMamba-T와 VMamba-B 모델을 실험한 결과, MambaLIFT는 부동 소수점 정밀도 수준에서 수치적 보존을 달성했습니다. 픽셀 뒤집기 실험에서는 기존 MambaLRP보다 훨씬 높은 충실도 점수를 기록했다고 연구진은 주장했습니다.",
                "evidence": "Under mean-colour pixel flipping, it achieves significantly higher mean faithfulness scores than MambaLRP on both configurations and the highest scores among the evaluated methods, including Integrated Gradients with matched references."
              },
              {
                "subtitle": "메커니즘 분석의 한계",
                "desc": "메커니즘 수준의 분석을 통해 기여도를 보존할 수는 있지만, 이것이 곧바로 인과적인 효과를 의미하지는 않는다고 밝혔습니다. 즉, 예측값의 차이를 설명할 수는 있어도 실제 개입 효과를 추정하거나 인과적 타당성을 확립하는 것은 아니라는 겁니다.",
                "evidence": "Mechanism-level analyses further show that exact relevance conservation does not imply additive effects under finite interventions: the mechanism decomposition accounts for the reference-relative logit difference but does not estimate intervention effects or establish causal validity."
              }
            ],
            "one_line": "VMamba 모델의 예측 근거를 분석하는 MambaLIFT 기법을 제안했어요.",
            "topic_tag": "AI 모델·학습법",
            "limit": "이 분석 방식은 예측값의 차이를 설명할 뿐이며, 실제 개입에 따른 효과를 추정하거나 인과관계를 증명하는 것은 아닙니다.",
            "limit_evidence": "Mechanism-level analyses further show that exact relevance conservation does not imply additive effects under finite interventions: the mechanism decomposition accounts for the reference-relative logit difference but does not estimate intervention effects or establish causal validity."
          },
