                "desc": "기본 예측 결과와 과거 정량적 강수 추정(QPE) 및 가강수량(PWV) 관측 데이터를 바탕으로 멀티모달 맥락을 선택하고 규모별 조절 방식을 써서 잔차 보정값을 찾아냈다는 거예요.",
                "evidence": "Conditioned on the base nowcast and historical quantitative precipitation estimation (QPE) and precipitable water vapor (PWV) observations, the corrector selects multimodal context and employs scale-aware modulation to estimate residual corrections."
