                "desc": "연구진은 최근에 나온 값 집합 반복 틀을 활용해 과거 기록에 의존하는 정책으로 이 문제들을 해결하는 다항 시간 알고리즘을 제시했는데요, 이 알고리즘은 최적 보상과의 오차를 입실론(ϵ) 이내로 잡고 비용 위반도 델타(δ) 이하로 제한하면서 어떤 기록에서든 행동 분포를 다항 시간에 계산해 낸다는 겁니다.",
