            "easy1_desc": "연구진은 최근 대형 언어 모델(LLM)을 써서 실행 가능한 프로그램을 만드는 연구를 살펴봤는데요, 주로 모델을 최적화 도구로만 써 왔다는 거예요. 뭔 소리냐면, 모델이 가진 지식을 시스템 수준 사이로 옮겨 주는 능력을 제대로 보지 못했다는 말이에요. 쉽게 말하면, 똑똑한 모델의 능력을 그대로 쓰기만 하고 다른 곳으로 넘겨줄 생각은 못 했던 셈이에요.",
            "easy1_evidence": "However, prior work has mainly treated LLMs as optimizers, overlooking their ability to transfer knowledge across system levels.",
            "easy2_title": "시스템 2의 능력을 시스템 0으로 옮겨서 성능은 높이고 시간은 줄여 봤어요",
            "easy2_desc": "그래서 연구진은 시스템 2의 능력을 시스템 0으로 옮기는 프로그램 증류(PD)라는 틀을 제안했는데요, 학습할 때는 대형 언어 모델이 지식과 전략을 주고 배포할 때는 학생 프로그램이 정책을 실행하도록 만들었어요. 그 결과 성능은 더 좋아지면서 추론 시간은 줄어드는 장점이 생겼다는 거예요. 대신 구조를 고치는 방법이 매개변수를 고치는 것보다 성공률은 조금 낮지만 더 큰 이득을 가져온다는 점도 같이 확인됐다고 합니다.",
