            "easy1_desc": "과학과 공학, 의료 분야에서 널리 쓰이는 편미분 방정식(PDE)을 이용해 시뮬레이션을 하려다 보면 계산 비용이 너무 많이 든다는 문제가 있는데요, 기존의 베이지안 신경 연산자(vBNO)를 그대로 쓰면 오차가 생기기도 한다는 거예요. 연구진은 이 연산자의 부족한 부분을 채우기 위해 오차 추정값을 활용하는 방법을 알아봤는데요, 결국 정확한 예측을 가로막는 한계를 보완할 필요가 있었다는 말이에요.",
