                "desc": "비선형 반응-확산 벤치마크와 자기공명영상(MRI)을 활용한 신경교종 매개변수 추정, 그리고 제조 불확실성이 있는 건물 외벽의 단열재 최적화 등 여러 사례에 적용해 봤는데요, 그 결과 기존 베이지안 신경 연산자(vBNO)보다 적은 훈련 시뮬레이션으로도 더 정확한 결과를 보여줬다는 겁니다.",
                "evidence": "We demonstrate RI-BNO on a non-linear reaction-diffusion benchmark with DeepONet and latent-subspace architectures, Markov chain Monte Carlo inference of glioma parameter fields from magnetic resonance imaging, and Monte Carlo risk-averse optimization of three-dimensional thermal breaks in building envelopes under manufacturing uncertainty."
