            "easy1_desc": "영화 같은 긴 영상에서는 화면 전환과 소리가 딱 맞아떨어지지 않고 대사가 장면을 이어주거나 침묵이 흐르기도 하는데요, 기존의 소리-영상 생성 기술은 이 둘의 시간 흐름을 따로따로 조절하지 못했다는 문제가 있었습니다. 그래서 영상이 길어지면 침묵해야 할 때 엉뚱하게 말을 하거나 화면 밖 사람 입이 움직이는 오류가 생겼다는 거예요. 뭔 소리냐면, 화면과 소리의 타이밍이 어긋나서 어색한 결과가 나온다는 말입니다.",
