            "easy2_evidence": "To enable fine-grained cinematic control, we present DECOUPAGE, a screenplay-driven framework for long-form, multi-shot, and multi-character joint audio-video generation.",
            "topic": "오랜 시간 동안 여러 장면이 나오는 영상에서 화면 전환과 소리의 타이밍을 따로 조절하여 자연스럽게 만들어내는 기술에 대한 이야기예요.",
            "topic_evidence": "To enable fine-grained cinematic control, we present DECOUPAGE, a screenplay-driven framework for long-form, multi-shot, and multi-character joint audio-video generation.",
