                "desc": "화면과 소리의 경계를 무조건 묶지 않고 각각 독립된 영역으로 나눈 뒤 일관된 캐릭터 정체성 아래에서 작동하도록 만들었는데요. 뭔 소리냐면, 화면의 움직임과 소리의 타이밍을 서로 간섭받지 않게 따로 조절한다는 말입니다.",
                "evidence": "Rather than coupling modality boundaries by default, DECOUPAGE uncouples generation into independently bounded visual and acoustic tracks governed by persistent character identities."
