            "easy1_desc": "유방암 진단을 할 때 왜 여러 가지 검사를 섞어 쓰는지 살펴봤는데요, 각각의 검사 방법마다 원리가 달라서 서로 보완해 주는 정보가 필요하거든요. 그런데 어느 한 가지 방법만으로는 정확한 진단에 필요한 구조나 기능을 다 담아내지 못한다는 거예요. 쉽게 말하면, 한 가지 검사만으로는 유방암의 모든 상태를 완벽하게 알기 어렵다는 셈이에요.",
