          "canon_id": "2611.18747",
          "title": "Video-as-Experience: Learning Computer Use via Audio-Visual Understanding",
          "field": "cs.AI",
          "sources": [
            "cs.AI"
          ],
          "links": {
            "arxiv": "https://arxiv.org/abs/2611.18747"
          },
