            "easy1_title": "지연이 튀는 바람에 약속 시간을 자주 어기게 됐습니다",
            "easy1_desc": "상호작용형 대규모 언어 모델(LLM) 서비스에서는 첫 토큰 생성 시간(TTFT)과 토큰 간 생성 시간(TBT)의 서비스 수준 목표(SLO)를 맞춰야 하는데요, 여러 요청을 한꺼번에 처리하거나 나눌 때 모두 디코드 지연 현상이 나타난다고 해요. 지연이 생기면 묶음 안의 모든 요청이 밀리게 되고 긴 응답은 수백 단계를 거치기 때문에, 드문 지연만 발생해도 목표 위반이 아주 많이 일어난다는 겁니다. 기존 방식에서는 예측 지연이 목표치에 딱 맞게 사전 채움(prefill) 예산을 잡다 보니 오차나 호스트 멈춤을 버틸 여유가 없었다고 해요.",
