            "easy1_desc": "사람마다 걸을 수 있는 길이 다르듯 이동 편의성은 주변 환경만이 아니라 사용자 상태에 따라 달라진다는 건데요. 하지만 기존 평가 방식들은 이런 다양한 조건을 고려하지 않고 고정된 기준만 써왔다는 말이에요. 뭔 소리냐면, 로봇이나 장애인이 실제로 겪는 이동의 차이를 제대로 반영하지 못했다는 겁니다.",
